	for _, f := range result.Findings {
		if len(severities) > 0 {
			if _, ok := severities[strings.ToUpper(string(f.Severity))]; !ok {
				continue
			}
		}
		if len(categories) > 0 {
			if _, ok := categories[string(scan.Categorize(f))]; !ok {
				continue
			}
		}
		kept = append(kept, f)
	}
	out.Matched = len(kept)

	offset := in.Offset
	if offset < 0 {
		offset = 0
	}
	limit := in.Limit
	if limit <= 0 {
		limit = defaultFindingLimit
	}
	if limit > maxFindingLimit {
		limit = maxFindingLimit
	}
	out.Offset = offset

	if offset >= len(kept) {
		return out
	}
	end := offset + limit
	if end > len(kept) {
		end = len(kept)
	}
