// process. It names every field it copies, so a field added to scan.Finding
// arrives here as an omission rather than as an exposure — which is the same
// argument `expose` makes for an allow-list of tools.
func expose(f scan.Finding) finding {
	return finding{
		ID:          f.ID,
		Title:       f.Title,
		Description: f.Description,
		Severity:    string(f.Severity),
		Category:    string(scan.Categorize(f)),
		Source:      f.Source,
		File:        f.File,
		Line:        f.Line,
		Fingerprint: f.Fingerprint,
		PkgName:     f.PkgName,
		Version:     f.Version,
		FixedIn:     f.FixedIn,
		Resolution:  f.Resolution,
		References:  f.References,
	}
}

func upperSet(values []string) map[string]struct{} {
	return set(values, strings.ToUpper)
}

func lowerSet(values []string) map[string]struct{} {
	return set(values, strings.ToLower)
}

func set(values []string, normalise func(string) string) map[string]struct{} {
	out := make(map[string]struct{}, len(values))
	for _, v := range values {
		v = normalise(strings.TrimSpace(v))
		if v != "" {
			out[v] = struct{}{}
		}
	}
	return out
}
