	Licenses        bool `json:"licenses"`
	Misconfig       bool `json:"misconfigurations"`
	IgnoreUnfixed   bool `json:"ignore_unfixed"`
}

type registryOut struct {
	Slug       string `json:"slug" jsonschema:"DevDesk's own identifier for this entry"`
